// Generates a local Iconify bundle containing ONLY the icons used in the app.
// This lets us register icons offline (via addCollection) so <Icon icon="..." />
// renders instantly with zero runtime calls to api.iconify.design / simplesvg / unisvg.
//
// Re-run after adding new icons:  node scripts/generate-icon-bundle.mjs
import { readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { getIcons } from "@iconify/utils";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, "..");
const SCAN_DIRS = ["app", "components", "features", "lib"];
const OUT_FILE = join(ROOT, "lib", "iconify-bundle.ts");

// Collections we ship locally. Add a prefix here if you start using a new set.
// NOTE: keep longer prefixes before shorter ones that are substrings
// (e.g. "circle-flags" before "flag") so the regex matches greedily.
const COLLECTIONS = {
  solar: "@iconify-json/solar/icons.json",
  "circle-flags": "@iconify-json/circle-flags/icons.json",
  "material-symbols": "@iconify-json/material-symbols/icons.json",
  flag: "@iconify-json/flag/icons.json",
};

// Match `prefix:name` tokens for our known prefixes anywhere in source.
const prefixAlternation = Object.keys(COLLECTIONS).join("|");
const ICON_RE = new RegExp(`\\b(${prefixAlternation}):([a-z0-9]+(?:-[a-z0-9]+)*)`, "g");

function walk(dir, files = []) {
  for (const entry of readdirSync(dir)) {
    if (entry === "node_modules" || entry.startsWith(".")) continue;
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) walk(full, files);
    else if (/\.(tsx?|jsx?|mdx?)$/.test(entry)) files.push(full);
  }
  return files;
}

// 1. Collect used icon names, grouped by prefix.
const used = {}; // prefix -> Set(name)
for (const d of SCAN_DIRS) {
  const abs = join(ROOT, d);
  try {
    for (const file of walk(abs)) {
      const src = readFileSync(file, "utf8");
      let m;
      while ((m = ICON_RE.exec(src))) {
        (used[m[1]] ??= new Set()).add(m[2]);
      }
    }
  } catch {
    /* dir may not exist */
  }
}

// 2. Subset each collection to just the used icons.
const collections = [];
let total = 0;
const missing = [];
for (const [prefix, pkg] of Object.entries(COLLECTIONS)) {
  const names = [...(used[prefix] ?? [])].sort();
  if (names.length === 0) continue;
  const source = JSON.parse(readFileSync(join(ROOT, "node_modules", pkg), "utf8"));
  const subset = getIcons(source, names);
  if (!subset) continue;
  const found = Object.keys(subset.icons).length + Object.keys(subset.aliases ?? {}).length;
  for (const n of names) {
    if (!subset.icons[n] && !subset.aliases?.[n]) missing.push(`${prefix}:${n}`);
  }
  total += found;
  collections.push(subset);
}

// 3. Emit a typed TS module.
const banner = `// AUTO-GENERATED by scripts/generate-icon-bundle.mjs — do not edit by hand.
// Contains ${total} icons used across the app, bundled for offline rendering.
// Re-run: node scripts/generate-icon-bundle.mjs
import type { IconifyJSON } from "@iconify/react";

export const iconBundle: IconifyJSON[] = ${JSON.stringify(collections)};
`;
writeFileSync(OUT_FILE, banner);

console.log(`Wrote ${total} icons to lib/iconify-bundle.ts`);
if (missing.length) {
  console.warn(`\n⚠ ${missing.length} icon(s) not found in collections (will fall back to API):`);
  console.warn("  " + missing.join("\n  "));
}
